C={x["paper_id"]:x for x in json.loads((D/"interspeech-2025-nineteenth-d3-papers.json").read_text())["papers"]}; P={x["paper_id"]:x for x in json.loads((D/"interspeech-2025-papers.json").read_text())["papers"]}
N={
"chen25h_interspeech":("ASR should work across languages, accents, and dialects rather than only on well-resourced standard varieties.","A single average benchmark can hide failures on communities that have little representation in training or evaluation.","Report one multilingual score on a narrow, convenient test set.","Build a broad public test suite and an online evaluation process that makes language-variety performance visible.","ML-SUPERB 2.0 evaluates models on 200+ languages, accents, and dialects through DynaBench and compares five challenge submissions with baselines.","Language-identification accuracy and character error rate are reported separately for general, accented, and dialectal speech.","The best submission reports 23% absolute LID improvement and 18% CER reduction generally, with 30.2% lower CER and 15.7% higher LID accuracy on accented/dialectal data.","Challenge submissions, test-suite composition, and hidden evaluation define the boundary; the results do not prove equal service quality for every language variety."),
"balajishankar25_interspeech":("Child ASR needs a correction stage that fixes transcription errors without turning child-specific disfluencies into fluent but wrong text.","Child speech has unusual acoustics and language patterns, and child error-correction data are scarce.","Apply adult speech error correction directly to child hypotheses.","Create a large hypothesis-to-reference dataset for children and learn a generative correction model whose errors can be inspected by type.","CHSER contains 200K pairs across ages and speaking styles; fine-tuned generative correction is tested in zero-shot and ASR-fine-tuned settings.","Word error rate measures overall correction, while substitution, deletion, insertion, and disfluency analysis show which errors are changed.","The paper reports up to 28.5% relative WER reduction zero-shot and 13.3% after ASR fine-tuning, but insertions and child disfluencies remain difficult.","The corpus, languages, ASR hypotheses, and correction model bound the result; preserving clinically meaningful disfluencies outside these settings remains open."),
"cm25_interspeech":("An ASR system should recognize speech played through a loudspeaker, not only clean speech recorded directly by a microphone.","Loudspeaker playback changes the acoustic path and can add coloration, reverberation, and level differences that the recognizer may mistake for speech variation.","Train and test on direct recordings, then assume the model will transfer to playback speech.","Measure the distribution shift caused by loudspeaker emission and evaluate recognition under that realistic channel.","The paper studies ASR performance for loudspeaker-emitted speech and compares recognition across the tested playback conditions.","Word error rate exposes the channel penalty; the useful distinction is speech content versus the acoustic path that carries it.","The paper reports a measurable ASR impact from loudspeaker emission under its experimental conditions.","The result is bounded to the loudspeaker, room, microphones, and ASR systems tested; other devices and adaptive compensation remain open."),
"christodoulidou25_interspeech":("Researchers need vowel measurements from child field recordings without manually transcribing and aligning every sample.","Child speech, dialect, recording conditions, and imperfect boundaries make automatic alignment unreliable.","Trust an automatic transcript and forced alignment without checking its acoustic measurements.","Use a semi-automatic pipeline, manually correct transcripts, and adapt the alignment model toward the child dialect.","WhisperX transcription and MFA alignment are evaluated on 275 Scottish-English children; acoustic vowel measures are compared with manual annotation.","Agreement of vowel measures with manual data is the target; transcript correction and acoustic-model adaptation are separate interventions.","Manual correction improves measures, adaptation helps, and more training data does not automatically add improvement.","The result is tied to Scottish English, field recordings, and vowel measurements; other ages, dialects, and measures need separate validation."),
"choi25h_interspeech":("Clinical speech studies need acoustic features that mean the same thing when extracted by different tools.","OpenSMILE, Praat, and Librosa can implement nominally similar features differently, changing a model's clinical conclusion.","Use one toolkit and treat its feature names as interchangeable with another toolkit's names.","Standardize extraction settings, compare tools directly, and test whether disagreements change group classification.","Three toolkits are applied to 77 schizophrenia-spectrum and 87 control speakers; correlations and classification performance are compared.","Feature correlations, agreement for F0/formants, and AUC reveal whether a feature is reproducible and useful for discrimination.","F0 percentile agreement is high, but F0 variation and formants can disagree or even correlate negatively; F0 mean, HNR, and MFCC1 exceed AUC .70 in the reported classification.","The clinical groups, recordings, parameter choices, and tool versions define the boundary; no clinical diagnosis or deployment safety follows from these correlations."),
"baihaqi25_interspeech":("A conversational agent should build rapport by responding proactively, personally, and with small listener signals rather than waiting for explicit requests.","Naturalness depends on timing and interaction, so a response strategy can affect both dialogue flow and a person's willingness to share.","Optimize a language model for task content while ignoring backchannels and stalls.","Prompt an LLM with a coordinated strategy for proactive behavior, personalization, and aizuchi backchannels, then measure both conversation and participant outcomes.","CO-STAR and few-shot prompts drive a robot in human-robot interaction; stalls, dialogue similarity, robot backchannels, participant behavior, and questionnaires are evaluated.","The paper separates system behavior from participant behavior and subjective reports rather than treating one dialogue score as rapport.","The integrated strategy is reported to improve behavioral and subjective rapport measures.","The study is bounded to the robot, prompts, participants, and short interaction protocol; long-term trust, cultural variation, and causal attribution remain open."),
"chung25_interspeech":("Speech restoration should use clues about the recording environment to undo distortion without mistaking the environment for speech content.","The same linguistic content can be damaged differently by noise, reverberation, or other conditions.","Condition a generator only on linguistic or speaker representations.","Add an acoustic-context representation that describes the distortion and its intensity, then condition the restoration model on it.","ACX refines CLAP-derived environmental embeddings and conditions the diffusion restoration model UNIVERSE++ across distortion conditions.","Restoration quality and stability across conditions compare context-aware and content-based conditioning; variability itself is an evaluation target.","The paper reports better restoration and reduced performance variability with acoustic context.","The result is tied to the distortion set, CLAP features, and diffusion backbone; unseen devices, rooms, and perceptual listeners remain open."),
"baihaqi25b_interspeech":("A virtual agent should move in ways that fit what it is saying without requiring a hand-written rule for every situation.","Rules do not generalize, while purely data-driven gesture generation is costly and often tied to one embodiment.","Choose gestures from fixed rules or train a large motion generator for each agent.","Use an LLM to plan context and select reusable primitive actions that can be adapted across agents.","The proposed model uses LLM-driven primitive action selection for co-speech motion in virtual agents and robots.","The key object is the mapping from dialogue context to a sequence of primitive actions; the paper's abstract does not expose a complete quantitative comparison.","The paper presents a flexible and scalable approach, but the preserved evidence does not establish a numerical gain.","Full mechanism, baselines, human judgments, and cross-embodiment transfer require the paper's detailed evaluation; the result is not a claim of human-like motion."),
"chowdhury25_interspeech":("Speech features used in behavioral or clinical models should measure the intended behavior consistently across people and contexts.","Open-source tools can disagree, and those disagreements can change model performance unevenly across demographic groups.","Extract features from a familiar toolkit and assume the outputs are reliable.","Compare tools directly in the target population and test how feature differences alter models and group behavior.","OpenSMILE and Praat features are evaluated on adolescents with autism from audio-visual recordings, with model performance compared across contexts and demographics.","Feature agreement and downstream classification are both measured; this connects measurement reliability to fairness rather than stopping at correlation.","The paper reports considerable tool variation that influences model performance across context and demographic groups.","The population, features, tools, and behavioral tasks define the boundary; the study does not identify one universally correct toolkit."),
"damianos25_interspeech":("ASR should adapt to a new or low-resource domain when labels are scarce or noisy.","Pseudo-label errors can reinforce themselves, while self-supervised adaptation alone may not learn the task boundary.","Fine-tune only on the small labeled target set or apply one adaptation technique in isolation.","Cascade self-supervised representation adaptation with pseudo-label training so each stage prepares the next.","MSDA evaluates a two-stage Meta PL pipeline for Greek and weakly supervised ASR, with ablations of the cascade.","Recognition error and ablations test whether the order of self-supervision and self-training matters.","The paper reports state-of-the-art results and finds the cascading combination necessary in its experiments.","The languages, pseudo-label quality, source models, and domain shifts bound the claim; robustness to severely wrong pseudo-labels remains open."),
"ahn25b_interspeech":("An audio captioner should describe what happened naturally and accurately, not exploit a similarity score with repeated or awkward words.","CLAP rewards can favor semantically related phrases while ignoring repetition and human naturalness.","Optimize one embedding similarity metric directly.","Combine CLAP similarity with repetition penalties, clipping, and LLM feedback during reward optimization.","CRRP trains an automated audio-captioning system with a stabilized CLAP reward and an LLM evaluator; semantic, human, and AI assessments are compared.","The reward combines semantic alignment and language naturalness, while multiple evaluations expose metric-specific behavior.","The paper reports strong semantic and human/AI evaluation results for the proposed reward system.","The result depends on caption datasets, evaluator prompts, and reward weighting; human agreement and out-of-domain audio remain open."),
"elleuch25_interspeech":("A dialect identifier should distinguish all Arabic varieties without requiring the data and model size of a full-resource system.","Dialects share language identity while differing in sound and vocabulary, and country coverage is uneven.","Train on a few prominent dialects or assume a large model automatically solves data imbalance.","Release broad data and compare pretrained encoders, data-size reduction, and model capacity directly.","ADI-20 contains 3,556 hours across 19 dialects plus MSA; ECAPA-TDNN and Whisper encoder systems are evaluated.","F1 measures dialect identification while controlled reductions test the value of data volume and parameters.","Using 30% of the original data causes only a small F1 decrease in the reported experiments.","The country/dialect inventory, labels, and data collection define the boundary; conversational code-switching and unrepresented varieties remain open."),
"biswas25b_interspeech":("Spoken-language understanding must fit a constrained device without losing intent and slot decisions.","Distillation can preserve a teacher's behavior that later quantization cannot represent.","Compress by distillation and quantize afterward as unrelated steps.","Train the student with distillation and quantization constraints together through multiple stages.","QUADS jointly optimizes a pretrained SLU model for low-bit regimes and evaluates it on SLURP and FSC.","Accuracy measures task retention, while GMACs and model size measure compute and storage cost.","The paper reports 71.13% SLURP and 99.20% FSC accuracy, 60–73x lower GMACs, and 83–700x smaller models with bounded degradation.","The result depends on tasks, bit settings, and hardware interpretation of the counts; latency and energy on deployed devices remain open."),
"ali25_interspeech":("A deepfake dataset for public figures should resemble the speech impersonation attacks people actually encounter, not merely contain clean synthetic clips.","Collection, segmentation, synthesis method, and speaker identity all affect how realistic a fake sounds.","Collect convenient speech and generate one kind of synthetic audio without checking human confusion.","Build a documented pipeline for high-quality bona-fide data, transcription-based segmentation, and several synthesis regimes, then measure naturalness and confusion.","The paper creates bona-fide and synthetic speech for ten public figures and reports NISQA-TTS and human misclassification.","Dataset composition, automated naturalness, and human confusion measure different parts of realism.","The dataset reports NISQA-TTS naturalness 3.69 and a highest human misclassification rate of 61.9%.","The ten figures, synthesis systems, listeners, and dataset protocol bound the result; new generators and adversarially chosen public speech remain open."),
"araizaillan25_interspeech":("A hearing test for adolescents with cochlear implants should measure vocal-emotion perception in an interface they can tolerate and engage with.","Pseudospeech removes linguistic emotion clues, while interface burden can affect participation and test time.","Use a computer-only test and treat usability as separate from measurement validity.","Compare a robot and computer interface on the same emotion task, including sensitivity, duration, and participant preference.","Adolescents aged 10–17 complete EmoHI pseudospeech emotion tests with a computer and NAO robot; d-prime, duration, and usability are measured.","Sensitivity, test duration, and perceived usability/enjoyment expose the tradeoff between measurement equivalence and engagement.","Sensitivity is similar (.36 versus .37); the robot takes longer, is less usable, but is more enjoyable and engaging.","The participants, robot, pseudospeech task, and small sample bound the result; long-term adherence and general hearing-device populations remain open."),
"francis25_interspeech":("An augmentative communication system should let a minimally verbal child express personal concepts and a personally meaningful voice.","Fixed symbols and fixed voices limit relevance, identity, and the range of things a user can communicate.","Offer a static symbol board and one default synthetic voice.","Generate visual symbols and use zero-shot TTS so users can personalize both the concept representation and voice.","The proposed AAC system combines text-to-image generation with zero-shot TTS for children with autism.","The conceptual objects are symbol coverage, voice personalization, and eventual social validity; the paper's abstract does not report a completed comparative trial.","The paper presents a broader expressive design but leaves long-term communication outcomes for future study.","No causal benefit or clinical efficacy should be inferred; user satisfaction, safety, cultural fit, and long-term adaptation remain open."),
"broughton25_interspeech":("A diarization system should assign speech to the right people in meetings with many simultaneous speakers without a separate pipeline for every case.","Overlap and speaker-count variation make it hard to learn all mixture configurations, while modular systems accumulate errors.","Train on a few-speaker simulation or chain independent detection and clustering modules.","Use one end-to-end non-autoregressive model and scale pretraining across systematically represented eight-speaker mixtures.","EEND-TA is evaluated on AliMeeting, AMI, DIHARD III, and MagicData RAMC with speed and diarization error comparisons.","Diarization error rate measures missed, false, and wrongly attributed speech; multiple corpora test transfer across meeting conditions.","The paper reports 14.49% DER on DIHARD III and state-of-the-art results on the listed datasets.","The simulations, corpora, speaker counts, and model speed define the boundary; spontaneous conditions beyond these meetings remain open."),
"deluca25_interspeech":("Researchers need to see many dimensions of voice data together rather than inspect one acoustic measure at a time.","High-dimensional features are difficult to extract, subset, and interpret without a usable exploratory interface.","Export one feature table and rely on fixed plots or isolated measures.","Put feature extraction, dimensionality reduction, filtering, and projection into an interactive dashboard.","Voxplorer exposes precomputed high-dimensional voice data and can extract features from recordings directly for interactive exploration.","The object is an exploratory mapping from many acoustic dimensions to a visual projection; it is a research instrument rather than a predictive model.","The paper presents a reusable dashboard intended to broaden voice-analysis exploration; no scientific performance score is claimed.","Usability, projection choices, and feature-tool assumptions determine what researchers see; the dashboard does not establish causal voice categories."),
"birkholz25_interspeech":("An articulatory synthesizer should model not only sound traveling through the vocal tract but also sound radiating through its walls.","A simple physical model must reproduce speaker-specific radiation without adding an impractical number of parameters.","Ignore wall radiation or use one fixed radiation response for every speaker.","Represent each tract section as a damped spring-mass system and fit wall parameters to real speaker voicebars.","The simulated radiation from tube sections is compared with six speakers producing /b,d,g/ in vowel contexts, with parameters optimized to real spectra.","Frequency-domain root-mean-square error between simulated and natural voicebar spectra measures how well the physical model explains the radiation.","The paper reports 2.26–3.82 dB RMSE from 0–800 Hz and concludes the simple model can reproduce the spectra closely.","The six speakers, selected consonants/vowels, frequency range, and fitted parameters bound the claim; other speech sounds and independent physical validation remain open."),
"chen25l_interspeech":("A listener may want one sound from a spatial mixture, and the system should use both where it is and what it is.","Nearby sources can overlap spatially, so direction alone may not distinguish the target.","Apply a spatial beamformer using only a target direction.","Condition an ambisonic-to-ambisonic separator on direction plus semantic information about the target sound.","SoundSculpt is trained on synthetic and real ambisonic mixtures, with direction from pointing and semantic embeddings from visual/audio description.","Separation quality compares spatial-only and spatial-plus-semantic conditioning, especially for nearby secondary sources.","The paper reports that semantic conditioning helps when sources are spatially close and outperforms signal-processing baselines.","Synthetic/real mixtures, semantic encoders, and target descriptions define the boundary; spoken conversation and pointing errors remain open."),
"cao25_interspeech":("Children learning a second tonal variety must realize pitch targets while their physiology and first dialect continue to shape production.","Targets overlap in time and similar tones can interfere, so an error is not simply a failure to memorize a contour.","Treat each tone as an isolated fixed pitch template.","Analyze on-target and off-target realization as interacting targets shaped by physiology and dialect experience.","Pitch production from 139 Changli-exposed children aged 35–71 months is analyzed in the CL-CHILD corpus.","The comparison separates target approximation, physiological constraints, and mutual interference among tonal categories.","The paper reports universal physiological constraints, persistent dialect interference, and off-target forms arising from phonetic similarity and target interaction.","The age range, dialect exposure, corpus, and tone inventory bound the developmental claim; longitudinal and other language environments remain open."),
"chen25q_interspeech":("A neural vocoder should produce detailed speech quickly without adding aliasing, blur, or other audible artifacts.","GAN vocoders can be sharp and fast but their frequency behavior can create artifacts that aggregate quality scores miss.","Use a generic GAN vocoder and rely on its learned filters to suppress artifacts.","Add a learnable frequency-domain artifact filter that imposes explicit control over which spectral components pass.","AF-Vocoder inserts GAFilter into a GAN vocoder and tests reconstruction quality and artifact suppression across datasets and speakers.","The frequency filter is the intervention; reconstruction and artifact measures compare quality in-domain and for out-of-domain speakers.","The paper reports better reconstruction quality and artifact suppression than other GAN vocoders.","Datasets, speaker coverage, artifacts, and listening protocol define the claim; real-time hardware cost and unseen languages remain open."),
"bendom25_interspeech":("Researchers need emotional speech from people with Parkinson's disease to study how disease and emotion interact in voice.","Small clinical datasets make it hard to separate emotional variation from speaker, disease, and language variation.","Reuse a generic emotion corpus or collect labels without documenting participant and recording choices.","Create a dedicated New Zealand English database with multiple emotions, speakers, and acoustic analysis, then test human recognition.","EMOPARKNZ contains 1,950 recordings from 13 speakers across five emotions; acoustic measures and a 22-listener perception test are reported.","F0, intensity, rate, and five-way listener accuracy connect measurable speech changes to perceived emotion.","The paper reports emotion-dependent acoustic differences and 63% listener classification accuracy.","Thirteen speakers, New Zealand English, Parkinson's disease, and the selected emotions bound the resource; clinical severity and broader populations remain open."),
"chou25_interspeech":("A voice-conversion system should change emotional expression for a speaker it has never seen while preserving the words and identity.","Emotion and identity are entangled, and changing one can distort the other; unseen speakers remove the shortcut of memorized target voices.","Train a separate converter for each target speaker or treat all speech variation as one undifferentiated style code.","Use diffusion with disentangled content, speaker, and emotion mechanisms plus expressive guidance for zero-shot conversion.","The model is trained on a large emotional-speech corpus and evaluated on unseen speakers in in-domain and out-of-domain data.","Emotion accuracy, naturalness, and speech quality are separate targets; zero-shot splits test whether the conversion survives a new speaker.","The paper reports expressive converted speech with high emotional accuracy, naturalness, and quality on its reported tests.","The result is bounded to the training corpus, emotion set, diffusion design, and unseen-speaker protocol; identity verification, languages, and independent listening remain open."),
}
keys=["bp","wh","naive","ap","mech","math","ww","limits"]; notes=[]; claims=[]; md=["# INTERSPEECH 2025 nineteenth-pass full-paper notes","","Twenty-three additional official-PDF readings add mechanism contrasts across the subthemes; one selected PDF remained text-extraction-limited and is recorded in the capture manifest. Results are author-reported and not independently reproduced.",""]
for i,(pid,vals) in enumerate(N.items(),1):
 if pid not in C: continue
 d=dict(zip(keys,vals)); d.update({"paper_id":pid,"title":P[pid]["title"],"subtheme":C[pid]["subtheme"]}); notes.append(d); md += [f"## {i}. {d['subtheme']}","",f"**Paper:** [{d['title']}]({P[pid]['paper_url']})",f"**Evidence:** D3; PDF SHA-256 `{C[pid]['pdf_sha256']}`; full text captured.",""]
 for key,label in zip(keys,["Ordinary problem","Why hard","Naive attempt","Central move","Mechanism","Conceptual structure","What paper reports","Limits"]): md += [f"- **{label}:** {d[key]}"]
 md += [""]; claims.append({"claim_id":f"IS25-D3C19-{i:02d}","paper_id":pid,"subtheme":d["subtheme"],"claim":d["ww"],"evidence_depth":"D3","pdf_sha256":C[pid]["pdf_sha256"],"full_text_sha256":C[pid]["full_text_sha256"],"support_status":"paper-reported-not-independently-verified","independent_support_status":"not-established","limitations":d["limits"]})
(D/"interspeech-2025-nineteenth-d3-notes.json").write_text(json.dumps({"venue":"INTERSPEECH 2025","evidence_depth":"D3","notes":notes},indent=2,ensure_ascii=False)+"\n")
(D/"interspeech-2025-nineteenth-claim-ledger.json").write_text(json.dumps({"venue":"INTERSPEECH 2025","claim_count":len(claims),"claims":claims},indent=2,ensure_ascii=False)+"\n")
R.mkdir(exist_ok=True); (R/"INTERSPEECH_2025_NINETEENTH_D3_NOTES.md").write_text("\n".join(md)+"\n")
